create table if not exists public.locations (id bigint generated by default as identity primary key, name text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.employees (id bigint generated by default as identity primary key, email text not null unique, first_name text not null, last_name text not null, role integer not null check (role between 1 and 3), location_id bigint references public.locations(id), active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.shifts (id bigint generated by default as identity primary key, employee_id bigint not null references public.employees(id) on delete cascade, shift_date date not null, start_time time not null, end_time time not null, status text not null default 'planned' check (status in ('planned','confirmed','cancelled')), notes text, created_at timestamptz not null default now(), unique(employee_id, shift_date, start_time));
create table if not exists public.absences (id bigint generated by default as identity primary key, employee_id bigint not null references public.employees(id) on delete cascade, start_date date not null, end_date date not null, type text not null check (type in ('vacation','sick','permit','other')), status text not null default 'pending' check (status in ('pending','approved','rejected')), notes text, created_at timestamptz not null default now(), check(end_date >= start_date));
create table if not exists public.notifications (id bigint generated by default as identity primary key, employee_id bigint references public.employees(id) on delete cascade, target_role integer check (target_role between 1 and 3), title text not null, body text not null, read_at timestamptz, created_at timestamptz not null default now(), check(employee_id is not null or target_role is not null));
create index if not exists idx_shifts_employee_date on public.shifts(employee_id, shift_date);
create index if not exists idx_absences_employee_date on public.absences(employee_id, start_date, end_date);
create index if not exists idx_notifications_employee on public.notifications(employee_id, created_at desc);
create index if not exists idx_notifications_role on public.notifications(target_role, created_at desc);

alter table public.locations enable row level security;
alter table public.employees enable row level security;
alter table public.shifts enable row level security;
alter table public.absences enable row level security;
alter table public.notifications enable row level security;

create policy "authenticated users can read locations" on public.locations for select to authenticated using (true);
create policy "authenticated users can read employees" on public.employees for select to authenticated using (true);
create policy "authenticated users can read shifts" on public.shifts for select to authenticated using (true);
create policy "authenticated users can read absences" on public.absences for select to authenticated using (true);
create policy "authenticated users can read notifications" on public.notifications for select to authenticated using (true);
create policy "authenticated users can insert shifts" on public.shifts for insert to authenticated with check (true);
create policy "authenticated users can update shifts" on public.shifts for update to authenticated using (true) with check (true);
create policy "authenticated users can insert absences" on public.absences for insert to authenticated with check (true);
create policy "authenticated users can update absences" on public.absences for update to authenticated using (true) with check (true);
create policy "authenticated users can update notifications" on public.notifications for update to authenticated using (true) with check (true);